<?php
$adminPage='settings';$adminTitle='Products & access';$adminPermission='settings.manage';require __DIR__.'/../includes/admin_header.php';$notice='';$error='';$allowed=['features.card_funding','features.transfers','features.credit_applications','features.support_cases','system.maintenance_mode'];if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$action=$_POST['action']??'';if($action==='setting'){$key=$_POST['key']??'';if(!in_array($key,$allowed,true))throw new InvalidArgumentException('Setting is not editable.');$value=($_POST['enabled']??'0')==='1';$stmt=$pdo->prepare('INSERT INTO product_settings(setting_key,value_json,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE value_json=VALUES(value_json),updated_by=VALUES(updated_by)');$stmt->execute([$key,$value?'true':'false',$_SESSION['user_id']]);audit($pdo,'product_setting.changed','product_setting',$key,['enabled'=>$value]);$notice='Feature setting updated.';}elseif($action==='role'){requirePermission('roles.manage');$userId=(int)($_POST['user_id']??0);$role=$_POST['role']??'';$roles=['super_admin','operations','kyc_reviewer','credit_officer','support_agent','read_only_auditor'];if(!in_array($role,$roles,true)||$userId===(int)$_SESSION['user_id'])throw new InvalidArgumentException('Invalid or self-directed role change.');$pdo->prepare('UPDATE users SET role=?,is_admin=1,session_version=session_version+1 WHERE user_id=? AND is_admin=1')->execute([$role,$userId]);audit($pdo,'admin.role_changed','user',$userId,['role'=>$role]);$notice='Role updated and existing sessions invalidated.';}}catch(Throwable $e){$error=$e->getMessage();}}$settings=$pdo->query("SELECT * FROM product_settings WHERE setting_key LIKE 'features.%' OR setting_key='system.maintenance_mode' ORDER BY setting_key")->fetchAll();$admins=$pdo->query("SELECT user_id,full_name,email,role,is_active FROM users WHERE is_admin=1 ORDER BY full_name")->fetchAll();
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="app-grid"><section class="panel span-6"><h2>Safe feature toggles</h2><p class="muted">These switches are stored centrally. Financial services also enforce limits and fees server-side.</p><?php foreach($settings as $row):$enabled=json_decode($row['value_json'],true)===true;?><form method="post" class="admin-section-head"><?=csrfField()?><input type="hidden" name="action" value="setting"><input type="hidden" name="key" value="<?=e($row['setting_key'])?>"><div><strong><?=e(str_replace(['features.','system.','_'],['','',' '],$row['setting_key']))?></strong><br><span class="badge <?=$enabled?'active':'disabled'?>"><?=$enabled?'enabled':'disabled'?></span></div><input type="hidden" name="enabled" value="<?=$enabled?'0':'1'?>"><button class="button button-secondary"><?=$enabled?'Disable':'Enable'?></button></form><?php endforeach?></section><section class="panel span-6"><h2>Roles and permissions</h2><p class="muted">Role changes invalidate existing sessions. Self-role changes are blocked.</p><?php foreach($admins as $admin):?><form method="post" class="note compact-form"><?=csrfField()?><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$admin['user_id']?>"><span><strong><?=e($admin['full_name'])?></strong><br><small><?=e($admin['email'])?></small></span><select name="role" <?=$admin['user_id']===$_SESSION['user_id']?'disabled':''?>><?php foreach(['super_admin','operations','kyc_reviewer','credit_officer','support_agent','read_only_auditor'] as $role):?><option <?=$admin['role']===$role?'selected':''?>><?=$role?></option><?php endforeach?></select><button class="button button-secondary" <?=$admin['user_id']===$_SESSION['user_id']?'disabled':''?>>Save</button></form><?php endforeach?></section></div><?php require __DIR__.'/../includes/admin_footer.php';?>
